"""Run a named sequence of steps over some text."""

from pipeline.registry import lookup
from pipeline.steps import Truncate


def _parse(name: str):
    """Return (step_name, arg_string) from a step name string."""
    if ":" in name:
        step_name, _, arg = name.partition(":")
        return step_name, arg
    return name, None


def run_pipeline(text: str, names: list[str]) -> str:
    for name in names:
        step_name, arg = _parse(name)
        if step_name == "truncate":
            if arg is None or arg == "":
                raise ValueError("truncate requires a length argument")
            try:
                length = int(arg)
            except ValueError:
                raise ValueError(
                    f"truncate length must be an integer, got {arg!r}"
                )
            text = Truncate(length).apply(text)
        else:
            text = lookup(step_name).apply(text)
    return text

